const body = $json.body || $json;
const sendMailerRaw = body.sendMailer ?? body.send_a_mailer ?? body.customFields?.send_a_mailer;
const sendMailer = String(sendMailerRaw ?? '').trim().toLowerCase();
const shouldSend = ['yes', 'true', 'selected', 'send', 'send mailer', '1'].includes(sendMailer);

const required = ['firstName', 'lastName', 'address1', 'city', 'state', 'zip'];
const missing = required.filter((field) => !String(body[field] ?? '').trim());

return [{
  json: {
    shouldSend,
    missing,
    contactId: body.contactId,
    source: 'gohighlevel',
    openLetterOrder: {
      contacts: [
        {
          firstName: body.firstName,
          lastName: body.lastName,
          address1: body.address1,
          address2: body.address2 || '',
          companyName: body.companyName || '',
          city: body.city,
          state: body.state,
          zip: body.zip,
          phone: body.phone || '',
          email: body.email || '',
          propertyAddress: body.propertyAddress || body.address1,
          propertyCity: body.propertyCity || body.city,
          propertyState: body.propertyState || body.state,
          propertyZip: body.propertyZip || body.zip,
          campaign_phone: body.campaignPhone || '',
          meta_data: {
            ghl_contact_id: body.contactId || '',
            source: 'gohighlevel'
          }
        }
      ],
      productId: Number($vars.OLC_PRODUCT_ID),
      templateId: Number($vars.OLC_TEMPLATE_ID),
      name: `GHL mailer - ${body.firstName || ''} ${body.lastName || ''}`.trim(),
      returnAddress: {
        firstName: $vars.RETURN_FIRST_NAME,
        lastName: $vars.RETURN_LAST_NAME,
        companyName: $vars.RETURN_COMPANY_NAME,
        address1: $vars.RETURN_ADDRESS_1,
        address2: $vars.RETURN_ADDRESS_2 || '',
        city: $vars.RETURN_CITY,
        state: $vars.RETURN_STATE,
        zip: $vars.RETURN_ZIP,
        phoneNo: $vars.RETURN_PHONE || '',
        email: $vars.RETURN_EMAIL || ''
      },
      crmMode: 'zapier'
    }
  }
}];
